#!/usr/bin/env node
/*!
 * Offline sample generator.
 *
 * Produces every fixture the test suite needs from source, using only the
 * locked @jsquash/avif encoder (lossless, bit-exact) and the local ISOBMFF box
 * builder. No network, no pre-generated logs, no external binaries.
 *
 * Outputs samples/ plus samples/manifest.json describing each file, its
 * structural descriptor and expected hashes. Re-running is deterministic:
 * pixel content is generated by a pure painter and every box mutation is
 * length-preserving or offset-repaired.
 */

import { createHash } from 'node:crypto';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';

import {
  addConflictingIspe,
  ftyp,
  imir,
  injectProperties,
  irot,
  tamperIspe,
  tamperNclx,
  withSequenceBrand,
} from './boxes.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.join(here, '..');
const samplesDir = path.join(root, 'samples');
const require = createRequire(import.meta.url);

async function loadCodec(relEntry, wasmRel) {
  const entry = await import(relEntry);
  const jsPath = require.resolve(relEntry);
  const wasmPath = path.join(path.dirname(jsPath), wasmRel);
  await entry.init(await WebAssembly.compile(await readFile(wasmPath)));
  return entry;
}

const encEntry = await loadCodec('@jsquash/avif/encode.js', './codec/enc/avif_enc.wasm');
const decEntry = await loadCodec('@jsquash/avif/decode.js', './codec/dec/avif_dec.wasm');
const encode = encEntry.default;
const decode = decEntry.default;

/** Deterministic painter: same arguments always produce identical RGBA. */
function paint(width, height, seed = 1) {
  const rgba = new Uint8ClampedArray(width * height * 4);
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const i = (y * width + x) * 4;
      rgba[i] = (x * 37 + seed * 11) & 255;
      rgba[i + 1] = (y * 53 + seed * 7) & 255;
      rgba[i + 2] = (x * 11 + y * 13 + seed * 3) & 255;
      rgba[i + 3] = x === 0 && y === 0 ? 0 : (x * 17 + y * 19 + seed) & 255;
      if (rgba[i + 3] === 0 && !(x === 0 && y === 0)) rgba[i + 3] = 255;
    }
  }
  return rgba;
}

const sha256 = (bytes) => createHash('sha256').update(bytes).digest('hex');

function findBoxType(bytes, type) {
  for (let i = 0; i + 4 <= bytes.length; i++) {
    let match = true;
    for (let j = 0; j < 4; j++) {
      if (bytes[i + j] !== type.charCodeAt(j)) {
        match = false;
        break;
      }
    }
    if (match) return i;
  }
  throw new Error(`box type ${type} not found`);
}

async function losslessAvif(rgba, width, height) {
  const out = await encode({ data: rgba, width, height }, { lossless: true });
  return new Uint8Array(out);
}

const manifest = [];
async function emit(name, bytes, note = {}) {
  await writeFile(path.join(samplesDir, name), bytes);
  manifest.push({ file: `samples/${name}`, bytes: bytes.length, sha256: sha256(bytes), ...note });
}

await mkdir(samplesDir, { recursive: true });

// --- 1. boundary sizes ------------------------------------------------------
for (const [w, h] of [[1, 1], [1, 7], [7, 1], [2, 2], [33, 17], [256, 128]]) {
  const rgba = paint(w, h, w + h);
  const avif = await losslessAvif(rgba, w, h);
  const decoded = await decode(avif.buffer.slice(0));
  await emit(`size-${w}x${h}.avif`, avif, {
    kind: 'boundary-size',
    width: w,
    height: h,
    expectedRgbaSha256: sha256(rgba),
    decodedRgbaSha256: sha256(decoded.data),
  });
}

// --- 2. transparency fixture ------------------------------------------------
{
  const w = 12;
  const h = 9;
  const rgba = paint(w, h, 99);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const i = (y * w + x) * 4;
      if (x < 4) rgba[i + 3] = 0;
      else if (x < 8) rgba[i + 3] = 128;
      else rgba[i + 3] = 255;
    }
  }
  const avif = await losslessAvif(rgba, w, h);
  const decoded = await decode(avif.buffer.slice(0));
  await emit('alpha-zones.avif', avif, {
    kind: 'alpha',
    width: w,
    height: h,
    expectedRgbaSha256: sha256(rgba),
    decodedRgbaSha256: sha256(decoded.data),
  });
}

// --- 3. orientation fixtures (irot / imir) ----------------------------------
const baseW = 8;
const baseH = 5;
const baseRgba = paint(baseW, baseH, 5);
const baseAvif = await losslessAvif(baseRgba, baseW, baseH);
await emit('orient-1-identity.avif', baseAvif, {
  kind: 'orientation',
  orientation: 1,
  width: baseW,
  height: baseH,
  expectedRgbaSha256: sha256(baseRgba),
});

const orientationCases = [
  ['2-mirror-h', [imir(0)], 2],
  ['3-rotate-180', [irot(2)], 3],
  ['4-mirror-v', [imir(1)], 4],
  // EXIF 5 = mirror left-right then rotate 90 CW (irot angle 1).
  ['5-mirror-rotate', [imir(0), irot(1)], 5],
  ['6-rotate-90', [irot(1)], 6],
  ['8-rotate-270', [irot(3)], 8],
];
for (const [label, props, orientation] of orientationCases) {
  const wired = injectProperties(baseAvif, props);
  const decoded = await decode(wired.buffer.slice(0)); // must still decode
  await emit(`orient-${label}.avif`, wired, {
    kind: 'orientation',
    orientation,
    codedWidth: baseW,
    codedHeight: baseH,
    codedRgbaSha256: sha256(decoded.data),
  });
}

// --- 4. colour-space variants -----------------------------------------------
{
  const rgba = paint(6, 6, 3);
  const avif = await losslessAvif(rgba, 6, 6);
  const rejected = tamperNclx(avif, 9, 16, 9, false); // BT.2020/PQ/ICtCp
  await emit('colour-bt2020-reject.avif', rejected, {
    kind: 'colour-reject',
    cicp: [9, 16, 9],
    expectedErrorCode: 'AVIF_COLOUR_SPACE_UNSUPPORTED',
    width: 6,
    height: 6,
  });
}

// --- 5. dimension mismatch: conflicting ispe -------------------------------
{
  const rgba = paint(6, 6, 4);
  const avif = await losslessAvif(rgba, 6, 6);
  const tampered = addConflictingIspe(avif, 7, 6);
  await emit('dimension-conflict.avif', tampered, {
    kind: 'dimension-reject',
    expectedErrorCode: 'AVIF_DIMENSION_MISMATCH',
  });
}

// --- 6. animation / multi-frame ---------------------------------------------
{
  const rgba = paint(4, 4, 6);
  const avif = await losslessAvif(rgba, 4, 4);
  await emit('animated-sequence.avif', withSequenceBrand(avif), {
    kind: 'animation-reject',
    expectedErrorCode: 'AVIF_ANIMATION_UNSUPPORTED',
  });
}

// --- 7. corrupted inputs ----------------------------------------------------
{
  const good = new Uint8Array(await readFile(path.join(samplesDir, 'size-2x2.avif')));
  await emit('corrupt-truncated.avif', good.subarray(0, Math.floor(good.length / 2)), {
    kind: 'corrupt',
    expectedErrorCode: 'AVIF_TRUNCATED_BOX',
  });
  const flipped = new Uint8Array(good);
  // Flip a byte inside the mdat coded payload (not a box header) so structural
  // validation may pass while the AV1 decode is guaranteed to fail.
  const mdatType = findBoxType(flipped, 'mdat');
  const mdatSize = new DataView(flipped.buffer).getUint32(mdatType - 4);
  const payloadStart = mdatType + 4;
  const payloadEnd = mdatType - 4 + mdatSize;
  flipped[Math.min(payloadStart + 2, payloadEnd - 1)] ^= 0xff;
  await emit('corrupt-byteflip.avif', flipped, {
    kind: 'corrupt',
    note: 'structure parses; WASM AV1 decode must reject',
  });
  await emit('corrupt-ftyp-only.avif', ftyp(), {
    kind: 'corrupt',
    expectedErrorCode: 'AVIF_INVALID_BOX',
  });
  await emit(
    'corrupt-not-avif.png',
    Uint8Array.from([137, 80, 78, 71, 13, 10, 26, 10, 0, 0, 0, 13]),
    { kind: 'corrupt', expectedErrorCode: 'AVIF_NOT_AVIF' },
  );
}

// --- 8. oversized declared dimension (rejected before decode) ---------------
{
  const rgba = paint(2, 2, 8);
  const avif = await losslessAvif(rgba, 2, 2);
  await emit('oversized-ispe.avif', tamperIspe(avif, 20000, 20000), {
    kind: 'dimension-reject',
    expectedErrorCode: 'AVIF_DIMENSION_UNSUPPORTED',
  });
}

await writeFile(
  path.join(samplesDir, 'manifest.json'),
  JSON.stringify({ generatedAt: 'deterministic', samples: manifest }, null, 2),
);
console.log(`generated ${manifest.length} samples in ${path.relative(root, samplesDir)}`);
for (const e of manifest) console.log(` - ${e.file} (${e.kind})`);
